"""Network settings for all Hugging Face Hub traffic of the nightly sync job."""

import logging

import httpx2
from huggingface_hub import HfApi, set_client_factory
from huggingface_hub.utils._http import hf_request_event_hook

logger = logging.getLogger("app.network")

HUB_TIMEOUT = httpx2.Timeout(60.0, connect=5.0)
JOB_HEADERS = {"X-Acme-Job": "nightly-sync"}


def _apply_default_timeout(request: httpx2.Request) -> None:
    # HfApi methods pass `timeout=None` explicitly, which httpx2 treats as "no timeout" and which would override
    # the client default. Only fill in our timeout when the caller did not set any.
    timeout = request.extensions.get("timeout")
    if timeout is None or all(value is None for value in timeout.values()):
        request.extensions["timeout"] = HUB_TIMEOUT.as_dict()


def configure_hub_http(transport=None) -> None:
    def client_factory() -> httpx2.Client:
        # huggingface_hub shares the client returned here between all HfApi instances, and calls the factory again
        # to rebuild it after closing it (e.g. after a connection error).
        return httpx2.Client(
            transport=transport,
            headers=JOB_HEADERS,
            timeout=HUB_TIMEOUT,
            # Keep huggingface_hub's own hook (offline mode, request id, download counter, debug logging).
            event_hooks={"request": [hf_request_event_hook, _apply_default_timeout]},
            follow_redirects=True,
        )

    set_client_factory(client_factory)


def current_revision(repo_id: str) -> str | None:
    try:
        return HfApi().model_info(repo_id, revision="main").sha
    except (httpx2.TimeoutException, httpx2.NetworkError) as err:
        logger.warning("Cannot reach the Hugging Face Hub to get the revision of %s: %s", repo_id, err)
        return None

